<?php
declare(strict_types=1);require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if(in_array($action,['approve','hide'],true)){$status=$action==='approve'?'approved':'hidden';db()->prepare('UPDATE comments SET status=? WHERE id=?')->execute([$status,$id]);audit('MODERATE_COMMENT',$id,$status);flash('success','Comment status updated.');}redirect('admin/comments.php');}$items=db()->query('SELECT c.*,u.display_name,r.title FROM comments c JOIN users u ON u.id=c.user_id JOIN recipes r ON r.id=c.recipe_id ORDER BY c.created_at DESC')->fetchAll();$pageTitle='Comment moderation';require __DIR__.'/../includes/header.php';?>
<section class="admin-head"><div class="container"><span class="eyebrow light">Community safety</span><h1>Comment moderation</h1><nav class="admin-tabs"><a href="<?=e(url('admin/index.php'))?>">Overview</a><a href="<?=e(url('admin/recipes.php'))?>">Recipes</a><a class="active" href="<?=e(url('admin/comments.php'))?>">Comments</a><a href="<?=e(url('admin/users.php'))?>">Users</a><a href="<?=e(url('admin/settings.php'))?>">Settings</a><a href="<?=e(url('admin/audit.php'))?>">Audit log</a></nav></div></section><section class="section container"><div class="table-wrap"><table><thead><tr><th>Comment</th><th>User</th><th>Recipe</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($items as $c):?><tr><td><?=e(mb_strimwidth($c['body'],0,160,'…'))?><small><?=e(date('j M Y g:i a',strtotime($c['created_at'])))?></small></td><td><?=e($c['display_name'])?></td><td><a href="<?=e(url('recipe.php?id='.$c['recipe_id']))?>"><?=e($c['title'])?></a></td><td><span class="status status-<?=e($c['status']==='approved'?'approved':'rejected')?>"><?=e($c['status'])?></span></td><td><div class="action-row"><?php if($c['status']!=='approved'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><button class="button button-small button-success" name="action" value="approve">Approve</button></form><?php endif;?><?php if($c['status']!=='hidden'):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$c['id']?>"><button class="button button-small button-danger" name="action" value="hide">Hide</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
